-- =============================================================================
-- 门店商品价格快照库建表脚本（当前精简版）
-- 版本：v5  日期：2026-10-09
-- 目标：MySQL 8.0.16+；已部署：192.168.100.200 / retail_price_snapshot
-- 对象：7 张表 + 1 个视图
--   dim_store / dim_store_competitor_rel / store_snapshot
--   fact_store_category_snapshot / fact_store_product_snapshot
--   fact_store_promotion_snapshot / map_source_sku_standard
--   v_store_product_latest
-- 说明：CREATE TABLE IF NOT EXISTS 不会升级已有旧表；升级以实际迁移 SQL 为准。
-- =============================================================================

CREATE DATABASE IF NOT EXISTS `retail_price_snapshot`
  CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE `retail_price_snapshot`;

CREATE TABLE IF NOT EXISTS `dim_store` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `channel_code` varchar(32) NOT NULL COMMENT '渠道编码：meituan、eleme、jddj；qnh 表示牵牛花商家后台（一个后台覆盖多个销售渠道）',
  `store_code` varchar(128) NOT NULL COMMENT '门店稳定编码，由我方分配，不随平台会话变化',
  `store_name` varchar(255) NOT NULL COMMENT '门店名称（最近一次采集到的名称）',
  `store_role` varchar(32) NOT NULL COMMENT 'own 或 competitor',
  `source_store_id` varchar(128) DEFAULT NULL COMMENT '平台门店 ID（最近一次采集到的；每次采集的值另记在 store_snapshot.source_store_id）',
  `source_tenant_id` varchar(64) DEFAULT NULL COMMENT '平台租户 ID（牵牛花：租户ID；source_store_id 记仓库ID）',
  `brand_name` varchar(128) DEFAULT NULL COMMENT '连锁品牌名，如 乐购达超市',
  `source_brand_id` varchar(64) DEFAULT NULL COMMENT '平台品牌 ID（美团 poi_info.brand_id）',
  `province_name` varchar(64) DEFAULT NULL COMMENT '省份',
  `city_name` varchar(64) DEFAULT NULL COMMENT '城市',
  `district_name` varchar(64) DEFAULT NULL COMMENT '区县',
  `address` varchar(512) DEFAULT NULL COMMENT '门店地址',
  `contact_phones` varchar(255) DEFAULT NULL COMMENT '[v3] 门店联系电话，多个用 | 分隔',
  `longitude` decimal(10,6) DEFAULT NULL COMMENT '门店经度（GCJ-02）',
  `latitude` decimal(10,6) DEFAULT NULL COMMENT '门店纬度（GCJ-02）',
  `own_store_id` varchar(64) DEFAULT NULL COMMENT '自有门店时关联 qnh_data.data_store_info.store_id',
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT '是否仍在采集：1 是，0 否',
  `remark` varchar(512) DEFAULT NULL COMMENT '备注',
  `created_at` timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updated_at` timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_dim_store` (`channel_code`,`store_code`),
  KEY `idx_dim_store_role` (`store_role`,`is_active`),
  KEY `idx_dim_store_city` (`city_name`,`store_role`),
  KEY `idx_dim_store_name` (`store_name`(191)),
  KEY `idx_dim_store_source` (`channel_code`,`source_store_id`),
  CONSTRAINT `chk_dim_store_role` CHECK ((`store_role` in (_utf8mb4'own',_utf8mb4'competitor')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='门店维表：稳定门店编码及基础信息';

CREATE TABLE IF NOT EXISTS `dim_store_competitor_rel` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `own_channel_code` varchar(32) NOT NULL COMMENT '自有门店渠道编码',
  `own_store_code` varchar(128) NOT NULL COMMENT '自有门店稳定编码（dim_store.store_role = own）',
  `competitor_channel_code` varchar(32) NOT NULL COMMENT '竞对门店渠道编码',
  `competitor_store_code` varchar(128) NOT NULL COMMENT '竞对门店稳定编码（dim_store.store_role = competitor）',
  `distance_km` decimal(8,2) DEFAULT NULL COMMENT '两店距离（公里）',
  `priority` tinyint NOT NULL DEFAULT '1' COMMENT '对标优先级：1 主要竞对，2 次要竞对',
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT '是否仍在对标：1 是，0 否',
  `remark` varchar(512) DEFAULT NULL COMMENT '备注',
  `created_at` timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updated_at` timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_store_competitor_rel` (`own_channel_code`,`own_store_code`,`competitor_channel_code`,`competitor_store_code`),
  KEY `idx_store_competitor_rel_comp` (`competitor_channel_code`,`competitor_store_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='自有门店与竞对门店的对标关系';

CREATE TABLE IF NOT EXISTS `fact_store_category_snapshot` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `store_snapshot_id` char(36) NOT NULL COMMENT '门店采集版本 ID',
  `batch_id` char(36) NOT NULL COMMENT '采集批次 ID',
  `snapshot_hour` datetime NOT NULL COMMENT 'Asia/Shanghai 采集时间，精确到小时',
  `channel_code` varchar(32) NOT NULL COMMENT '渠道编码',
  `store_code` varchar(128) NOT NULL COMMENT '门店稳定编码',
  `category_key` varchar(255) NOT NULL COMMENT '[v2] 类目定位键：有平台 tag 时为 tag；否则一级为 name:一级名，二级为 name:一级名/二级名',
  `category_tag_id` varchar(64) DEFAULT NULL COMMENT '平台类目 tag（滚屏方式为空）',
  `category_name` varchar(255) NOT NULL COMMENT '类目名称原文',
  `parent_tag_id` varchar(64) DEFAULT NULL COMMENT '上级类目 tag，一级类目为 NULL',
  `parent_category_key` varchar(255) DEFAULT NULL COMMENT '[v3] 上级类目定位键（规则同 category_key），一级类目为 NULL',
  `category_level` tinyint NOT NULL DEFAULT '1' COMMENT '类目层级：1 一级，2 二级',
  `category_order` int DEFAULT NULL COMMENT '门店类目顺序（同级内）',
  `tag_type` int DEFAULT NULL COMMENT '平台类目类型原值：13 推荐、33 神价、2 活动、1 普通 等',
  `is_virtual` tinyint NOT NULL DEFAULT '0' COMMENT '是否运营虚拟类目（推荐、神价、活动等）：1 是',
  `platform_product_count` int DEFAULT NULL COMMENT '平台声明的该类目商品数',
  `captured_spu_count` int DEFAULT NULL COMMENT '本次实际采到的 SPU 数',
  `created_at` timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '入库时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_store_category_snapshot` (`store_snapshot_id`,`category_key`),
  KEY `idx_store_category_store` (`store_code`,`snapshot_hour`,`category_level`,`category_order`),
  KEY `idx_store_category_tag` (`store_code`,`category_tag_id`),
  KEY `idx_store_category_parent` (`store_snapshot_id`,`parent_category_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='门店类目树快照';

CREATE TABLE IF NOT EXISTS `fact_store_product_snapshot` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `batch_id` char(36) NOT NULL COMMENT '采集批次 ID',
  `store_snapshot_id` char(36) NOT NULL COMMENT '门店采集版本 ID',
  `snapshot_hour` datetime NOT NULL COMMENT 'Asia/Shanghai 采集时间，精确到小时',
  `collected_at` datetime(3) DEFAULT NULL COMMENT '该条记录实际采集时间（滚屏：最后一次看到的时间）',
  `capture_method` varchar(32) DEFAULT NULL COMMENT '采集方式，同 store_snapshot.capture_method',
  `channel_code` varchar(32) NOT NULL COMMENT '商品所在的销售渠道：meituan、eleme、jddj（牵牛花后台采集时，一个商品每个渠道一行）',
  `store_code` varchar(128) NOT NULL COMMENT '门店稳定编码',
  `store_name` varchar(255) NOT NULL COMMENT '门店名称',
  `store_role` varchar(32) NOT NULL COMMENT 'own 或 competitor',
  `category_name` varchar(255) DEFAULT NULL COMMENT '店内一级类目原文',
  `category_order` int DEFAULT NULL COMMENT '一级类目在门店里的顺序',
  `category_tag_id` varchar(64) DEFAULT NULL COMMENT '一级类目平台 tag',
  `sub_category_name` varchar(255) DEFAULT NULL COMMENT '店内二级类目原文',
  `sub_category_tag_id` varchar(64) DEFAULT NULL COMMENT '二级类目平台 tag',
  `platform_category_l1_id` varchar(32) DEFAULT NULL COMMENT '平台标准类目一级 ID',
  `platform_category_l1_name` varchar(128) DEFAULT NULL COMMENT '平台标准类目一级名称',
  `platform_category_l2_id` varchar(32) DEFAULT NULL COMMENT '平台标准类目二级 ID',
  `platform_category_l2_name` varchar(128) DEFAULT NULL COMMENT '平台标准类目二级名称',
  `platform_category_l3_id` varchar(32) DEFAULT NULL COMMENT '平台标准类目三级 ID',
  `platform_category_l3_name` varchar(128) DEFAULT NULL COMMENT '平台标准类目三级名称',
  `listing_key` char(64) NOT NULL COMMENT '商品定位键，规则见表注释',
  `source_spu_id` varchar(128) DEFAULT NULL COMMENT '平台 SPU ID（滚屏为空；牵牛花后台为后台 SPU）',
  `source_sku_id` varchar(128) DEFAULT NULL COMMENT '平台 SKU ID（只有带 SKU 的数据有）',
  `open_platform_id` varchar(64) DEFAULT NULL COMMENT '[后台] 开放平台标识',
  `product_name` varchar(512) NOT NULL COMMENT '商品名称原文，禁止改写',
  `spec_name` varchar(255) DEFAULT NULL COMMENT '规格原文',
  `upc` varchar(255) DEFAULT NULL COMMENT '商品条码',
  `store_inner_code` varchar(128) DEFAULT NULL COMMENT '[后台] 店内码（商家自填）',
  `article_no` varchar(64) DEFAULT NULL COMMENT '[后台] 货号',
  `weight_text` varchar(64) DEFAULT NULL COMMENT '重量 / 净含量原文，如 40克（g）',
  `sku_count` smallint DEFAULT NULL COMMENT '该 SPU 下 SKU 数',
  `has_multi_spec` tinyint DEFAULT NULL COMMENT '是否多规格（卡片按钮是「选规格」）：1 是，0 否',
  `front_display_price_amount` decimal(18,4) DEFAULT NULL COMMENT '前端展示价；牵牛花后台为该渠道零售价',
  `is_from_price` tinyint NOT NULL DEFAULT '0' COMMENT '展示价是否带「起」：1 是',
  `price_condition` varchar(32) DEFAULT NULL COMMENT '展示价适用条件，如 第1件、前3件',
  `user_final_price_amount` decimal(18,4) DEFAULT NULL COMMENT '有证据的用户到手价',
  `original_price_amount` decimal(18,4) DEFAULT NULL COMMENT '原价或划线价',
  `activity_price_amount` decimal(18,4) DEFAULT NULL COMMENT '活动价',
  `member_price_amount` decimal(18,4) DEFAULT NULL COMMENT '会员价',
  `multi_buy_text` varchar(64) DEFAULT NULL COMMENT '多件价文案，如 买2件¥15.8/件',
  `multi_buy_quantity` int DEFAULT NULL COMMENT '多件价件数',
  `multi_buy_unit_price_amount` decimal(18,4) DEFAULT NULL COMMENT '多件价单价',
  `discount_text` varchar(128) DEFAULT NULL COMMENT '折扣文案，如 0.02折 限1份',
  `limit_purchase_quantity` decimal(18,4) DEFAULT NULL COMMENT '限购数量',
  `promo_remaining_text` varchar(32) DEFAULT NULL COMMENT '优惠余量文案',
  `promotion_text` varchar(1024) DEFAULT NULL COMMENT '前端优惠文案',
  `purchase_price_amount` decimal(18,4) DEFAULT NULL COMMENT '[后台] 采购价',
  `purchase_price_unit` varchar(16) DEFAULT NULL COMMENT '[后台] 采购价单位，如 袋、份',
  `purchase_price_text` varchar(32) DEFAULT NULL COMMENT '[后台] 采购价原文（显示「无数据」时价格为空）',
  `month_sales_text` varchar(32) DEFAULT NULL COMMENT '月售文案原文，如 月售10、月售1000+',
  `month_sales_qty` int DEFAULT NULL COMMENT '月售数量（带 + 的取下限）',
  `want_to_buy_count` int DEFAULT NULL COMMENT '想买人数',
  `praise_rate_pct` decimal(5,2) DEFAULT NULL COMMENT '好评率（百分数）',
  `like_count` int DEFAULT NULL COMMENT '赞',
  `dislike_count` int DEFAULT NULL COMMENT '踩',
  `praise_count` int DEFAULT NULL COMMENT '好评数',
  `stock_text` varchar(32) DEFAULT NULL COMMENT '库存文案原文',
  `stock_quantity` decimal(18,4) DEFAULT NULL COMMENT '库存数量；牵牛花后台为渠道库存，显示「售罄」记 0',
  `stock_unit` varchar(16) DEFAULT NULL COMMENT '库存单位',
  `sale_status` varchar(32) NOT NULL DEFAULT 'unknown' COMMENT 'available、out_of_stock 或 unknown',
  `listing_status` varchar(16) DEFAULT NULL COMMENT '[后台] 渠道上架状态：on_shelf 已上架、off_shelf 已下架、not_online 未上线',
  `is_standard` tinyint DEFAULT NULL COMMENT '[后台] 是否标品（后台属性，与有无条码无关）',
  `is_promo_item` tinyint DEFAULT NULL COMMENT '[后台] 是否活动品',
  `is_recommended` tinyint DEFAULT NULL COMMENT '[后台] 是否力荐',
  `sellable_date_text` varchar(64) DEFAULT NULL COMMENT '[后台] 可售日期原文',
  `gift_bag_text` varchar(64) DEFAULT NULL COMMENT '[后台] 礼袋绑定原文',
  `selling_points` varchar(1024) DEFAULT NULL COMMENT '卖点文案',
  `picture_url` varchar(1024) DEFAULT NULL COMMENT '主图 URL',
  `other_text` varchar(512) DEFAULT NULL COMMENT '没识别出含义的价格 / 库存文案原文（正常为空）',
  `evidence_uri` varchar(512) DEFAULT NULL COMMENT '核对用截图路径（相对 store_snapshot.evidence_uri）',
  `evidence_video_time` varchar(16) DEFAULT NULL COMMENT '该商品在录像中的时间点，如 03:12.5',
  `created_at` timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '入库时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_store_product_snapshot` (`store_snapshot_id`,`channel_code`,`listing_key`),
  KEY `idx_store_product_history` (`store_code`,`channel_code`,`listing_key`,`snapshot_hour`),
  KEY `idx_store_product_category` (`store_code`,`snapshot_hour`,`category_order`),
  KEY `idx_store_product_upc` (`upc`,`snapshot_hour`),
  KEY `idx_store_product_name` (`product_name`),
  KEY `idx_store_product_batch` (`batch_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='门店商品快照（用户端滚屏 / 带 SKU 的数据 / 牵牛花后台）。listing_key = SHA2(定位串,256) 小写十六进制；定位串：有平台 SKU ID 为 sku:SKU ID，有平台 SPU ID 为 spu:SPU ID，否则有商品条码为 barcode:条码（牵牛花 App 列表页的「条码」，13 位 UPC 或 19 位后台内部码，不随改名变化），真正无条码时为 name:商品名（商品名先去首尾空白、连续空白合并为一个空格）。同一采集版本、同一渠道内仍重复的，按页面出现顺序在定位串末尾加 #2、#3。标 [后台] 的字段只有商家后台采集才有。匹配到的我方标准商品见 map_source_sku_standard（按 channel_code + listing_key 关联）。';

CREATE TABLE IF NOT EXISTS `fact_store_promotion_snapshot` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `store_snapshot_id` char(36) NOT NULL COMMENT '门店采集版本 ID',
  `batch_id` char(36) NOT NULL COMMENT '采集批次 ID',
  `snapshot_hour` datetime NOT NULL COMMENT 'Asia/Shanghai 采集时间，精确到小时',
  `channel_code` varchar(32) NOT NULL COMMENT '渠道编码',
  `store_code` varchar(128) NOT NULL COMMENT '门店稳定编码',
  `promo_key` varchar(255) NOT NULL COMMENT '优惠定位键：有券 ID 时为 id:券ID，否则为 text:优惠文案',
  `promo_type` varchar(32) NOT NULL DEFAULT 'other' COMMENT 'full_reduction 满减、new_customer 新客、coupon 店铺券 / 商品券 / 品牌券、delivery 配送费优惠、other',
  `promo_text` varchar(255) NOT NULL COMMENT '优惠文案原文，如 199减20、新客减1、满10减8',
  `coupon_id` varchar(64) DEFAULT NULL COMMENT '平台优惠券 ID',
  `activity_id` varchar(64) DEFAULT NULL COMMENT '平台活动 ID',
  `coupon_name` varchar(255) DEFAULT NULL COMMENT '优惠券名称原文，如 科赴神价券',
  `coupon_status` int DEFAULT NULL COMMENT '优惠券状态原值',
  `coupon_type` int DEFAULT NULL COMMENT '优惠券类型原值，如 117',
  `coupon_type_name` varchar(64) DEFAULT NULL COMMENT '优惠券类型名称原文，如 商品券',
  `activity_category` varchar(64) DEFAULT NULL COMMENT '活动分类原文，如 大牌联合',
  `threshold_amount` decimal(18,4) DEFAULT NULL COMMENT '门槛金额（满 X），无门槛为 0',
  `discount_amount` decimal(18,4) DEFAULT NULL COMMENT '优惠金额（减 Y / 券面额）',
  `promo_count` smallint NOT NULL DEFAULT '1' COMMENT '同一文案在页面上出现的次数（如多张同额商品券）',
  `display_order` smallint DEFAULT NULL COMMENT '页面展示顺序，从 1 开始',
  `coupon_created_at` datetime DEFAULT NULL COMMENT '平台记录的优惠券创建时间',
  `valid_start_at` datetime DEFAULT NULL COMMENT '有效期开始',
  `valid_end_at` datetime DEFAULT NULL COMMENT '有效期结束',
  `created_at` timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '入库时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_store_promotion` (`store_snapshot_id`,`promo_key`),
  KEY `idx_store_promotion_store` (`store_code`,`snapshot_hour`,`promo_type`),
  KEY `idx_store_promotion_coupon` (`coupon_id`,`snapshot_hour`),
  CONSTRAINT `chk_store_promotion_type` CHECK ((`promo_type` in (_utf8mb4'full_reduction',_utf8mb4'new_customer',_utf8mb4'coupon',_utf8mb4'delivery',_utf8mb4'other')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='门店优惠快照：满减、新客、配送费优惠，以及带 ID 和有效期的商品券 / 品牌券';

CREATE TABLE IF NOT EXISTS `map_source_sku_standard` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `channel_code` varchar(32) NOT NULL COMMENT '渠道编码',
  `listing_key` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '[新增] 平台商品定位键，规则见表头注释',
  `listing_type` varchar(16) NOT NULL DEFAULT 'sku' COMMENT 'sku（按平台 SKU ID）、spu（按平台 SPU ID）或 name（按商品名，滚屏数据）',
  `source_spu_id` varchar(128) DEFAULT NULL COMMENT '平台来源 SPU ID（滚屏数据为空）',
  `source_sku_id` varchar(128) DEFAULT NULL COMMENT '平台来源 SKU ID（滚屏数据为空）',
  `product_name` varchar(512) DEFAULT NULL COMMENT '[新增] 平台商品名原文，便于人工复核',
  `spec_name` varchar(255) DEFAULT NULL COMMENT '[新增] 平台规格名',
  `upc` varchar(255) DEFAULT NULL COMMENT '平台商品条码（匹配依据之一）',
  `standard_spu_id` varchar(64) DEFAULT NULL COMMENT '标准 SPU ID（qnh_data.goods_master_goods.spu）',
  `standard_sku_id` varchar(64) DEFAULT NULL COMMENT '标准 SKU ID（qnh_data.goods_master_goods.sku）',
  `match_status` varchar(32) NOT NULL DEFAULT 'unmatched' COMMENT 'matched、unmatched 或 review',
  `match_method` varchar(32) DEFAULT NULL COMMENT 'upc、name_spec、manual 等',
  `match_score` decimal(6,4) DEFAULT NULL COMMENT '自动匹配置信度 0~1',
  `reviewed_by` varchar(64) DEFAULT NULL COMMENT '人工复核人',
  `reviewed_at` datetime DEFAULT NULL COMMENT '人工复核时间',
  `remark` varchar(512) DEFAULT NULL COMMENT '备注',
  `created_at` timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updated_at` timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_map_listing` (`channel_code`,`listing_key`),
  UNIQUE KEY `uk_map_source_sku` (`channel_code`,`source_sku_id`),
  KEY `idx_map_source_spu` (`channel_code`,`source_spu_id`),
  KEY `idx_map_standard_sku` (`standard_sku_id`),
  KEY `idx_map_upc` (`upc`),
  KEY `idx_map_name` (`product_name`(191)),
  KEY `idx_map_status` (`match_status`),
  CONSTRAINT `chk_map_listing_type` CHECK ((`listing_type` in (_utf8mb4'barcode',_utf8mb4'sku',_utf8mb4'spu',_utf8mb4'name'))),
  CONSTRAINT `chk_map_match_status` CHECK ((`match_status` in (_utf8mb4'matched',_utf8mb4'unmatched',_utf8mb4'review')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='平台商品与我方标准商品的匹配关系。listing_key 规则同 fact_store_product_snapshot（不含 #2 序号）；listing_type barcode 表示按商品条码定位（牵牛花 App）。';

CREATE TABLE IF NOT EXISTS `store_snapshot` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `store_snapshot_id` char(36) NOT NULL COMMENT '门店采集版本 ID（UUID）',
  `batch_id` char(36) NOT NULL COMMENT '采集批次 ID（UUID），一个批次可包含多家门店',
  `snapshot_hour` datetime NOT NULL COMMENT 'Asia/Shanghai 采集时间，精确到小时',
  `channel_code` varchar(32) NOT NULL COMMENT '渠道编码',
  `store_code` varchar(128) NOT NULL COMMENT '门店稳定编码',
  `store_name` varchar(255) NOT NULL COMMENT '本次采集到的门店名称',
  `store_role` varchar(32) NOT NULL COMMENT 'own 或 competitor',
  `source_store_id` varchar(128) DEFAULT NULL COMMENT '本次采集时的平台门店 ID',
  `status` varchar(16) NOT NULL DEFAULT 'running' COMMENT 'running、success、partial、failed',
  `capture_method` varchar(32) DEFAULT NULL COMMENT '采集方式：h5_api_replay、h5_passive、h5_scroll_text、app_ui 等',
  `collector_version` varchar(64) DEFAULT NULL COMMENT '采集程序版本',
  `device_id` varchar(128) DEFAULT NULL COMMENT '[v2] 采集用的手机（ADB 序列号或 IP:端口）',
  `started_at` datetime(3) NOT NULL COMMENT '采集开始时间',
  `finished_at` datetime(3) DEFAULT NULL COMMENT '采集结束时间',
  `stop_reason` varchar(128) DEFAULT NULL COMMENT '[v2] 结束原因，如 页面已到底、达到最大滚动次数',
  `screen_count` int DEFAULT NULL COMMENT '[v2] 滚屏方式采集的屏数',
  `covered_categories` varchar(2048) DEFAULT NULL COMMENT '[v2] 本次覆盖的一级类目（分段采、没采全时填写，| 分隔）',
  `evidence_uri` varchar(512) DEFAULT NULL COMMENT '[v2] 录像 / 截图 / 原始文件的存放位置（目录或对象存储前缀）',
  `manifest_uri` varchar(512) DEFAULT NULL COMMENT '[v5] 最终不可变采集清单路径；progress/result 文件独立存放',
  `manifest_sha256` char(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL COMMENT '[v5] 最终 manifest 原始字节的 SHA-256',
  `csv_sha256` char(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL COMMENT '[v5] 最终 CSV 原始字节的 SHA-256',
  `store_url` varchar(1024) DEFAULT NULL COMMENT '[v3] 本次采集的门店页面网址',
  `request_longitude` decimal(10,6) DEFAULT NULL COMMENT '采集时定位经度（价格、可售范围随定位变化）',
  `request_latitude` decimal(10,6) DEFAULT NULL COMMENT '采集时定位纬度',
  `request_region_id` varchar(32) DEFAULT NULL COMMENT '平台区域 ID（美团 region_id）',
  `distance_text` varchar(32) DEFAULT NULL COMMENT '[v3] 门店距离文案原文，如 3.5km（随采集定位变化）',
  `distance_km` decimal(8,2) DEFAULT NULL COMMENT '[v3] 门店距离（公里），按文案解析',
  `store_score` decimal(3,1) DEFAULT NULL COMMENT '门店评分',
  `comment_count` int DEFAULT NULL COMMENT '评价数',
  `min_order_amount` decimal(18,4) DEFAULT NULL COMMENT '起送价',
  `shipping_fee_amount` decimal(18,4) DEFAULT NULL COMMENT '配送费（原价）',
  `shipping_fee_tip` varchar(64) DEFAULT NULL COMMENT '配送费展示文案，如 配送 ¥4',
  `packing_fee_amount` decimal(18,4) DEFAULT NULL COMMENT '包装费',
  `avg_delivery_minutes` int DEFAULT NULL COMMENT '平均配送时长（分钟）',
  `delivery_time_text` varchar(64) DEFAULT NULL COMMENT '[v2] 配送时长文案原文，如 配送约64分钟',
  `business_hours` varchar(128) DEFAULT NULL COMMENT '营业 / 配送时段',
  `store_sell_status` int DEFAULT NULL COMMENT '平台门店营业状态原值',
  `bulletin` varchar(2048) DEFAULT NULL COMMENT '[v2] 门店公告原文',
  `platform_spu_total_text` varchar(64) DEFAULT NULL COMMENT '平台展示的在售商品数文案，如 约8000件',
  `category_count` int DEFAULT NULL COMMENT '本次采集到的类目数',
  `expected_spu_count` int DEFAULT NULL COMMENT '各类目平台声明商品数之和（去重前）',
  `captured_spu_count` int DEFAULT NULL COMMENT '本次入库 SPU（商品卡片）数（去重后）',
  `captured_sku_count` int DEFAULT NULL COMMENT '本次入库 SKU 数（去重后，滚屏方式为空）',
  `raw_record_count` int DEFAULT NULL COMMENT '本次原始记录数',
  `error_message` varchar(1024) DEFAULT NULL COMMENT '失败或部分成功原因',
  `created_at` timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '入库时间',
  `updated_at` timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_store_snapshot` (`store_snapshot_id`),
  UNIQUE KEY `uk_store_snapshot_manifest` (`channel_code`,`store_code`,`manifest_sha256`),
  KEY `idx_store_snapshot_batch` (`batch_id`,`store_code`),
  KEY `idx_store_snapshot_store` (`channel_code`,`store_code`,`status`,`snapshot_hour`),
  KEY `idx_store_snapshot_status` (`status`,`started_at`),
  CONSTRAINT `chk_store_snapshot_role` CHECK ((`store_role` in (_utf8mb4'own',_utf8mb4'competitor'))),
  CONSTRAINT `chk_store_snapshot_status` CHECK ((`status` in (_utf8mb4'running',_utf8mb4'success',_utf8mb4'partial',_utf8mb4'failed')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='门店采集版本：一次完整门店采集一行，含门店当时的经营指标与完整性统计';

