y_l2_name` AS `platform_category_l2_name`,`p`.`platform_category_l3_id` AS `platform_category_l3_id`,`p`.`platform_category_l3_name` AS `platform_category_l3_name`,`p`.`listing_key` AS `listing_key`,`p`.`source_spu_id` AS `source_spu_id`,`p`.`source_sku_id` AS `source_sku_id`,`p`.`open_platform_id` AS `open_platform_id`,`p`.`product_name` AS `product_name`,`p`.`spec_name` AS `spec_name`,`p`.`upc` AS `upc`,`p`.`store_inner_code` AS `store_inner_code`,`p`.`article_no` AS `article_no`,`p`.`weight_text` AS `weight_text`,`p`.`sku_count` AS `sku_count`,`p`.`has_multi_spec` AS `has_multi_spec`,`p`.`front_display_price_amount` AS `front_display_price_amount`,`p`.`is_from_price` AS `is_from_price`,`p`.`price_condition` AS `price_condition`,`p`.`user_final_price_amount` AS `user_final_price_amount`,`p`.`original_price_amount` AS `original_price_amount`,`p`.`activity_price_amount` AS `activity_price_amount`,`p`.`member_price_amount` AS `member_price_amount`,`p`.`multi_buy_text` AS `multi_buy_text`,`p`.`multi_buy_quantity` AS `multi_buy_quantity`,`p`.`multi_buy_unit_price_amount` AS `multi_buy_unit_price_amount`,`p`.`discount_text` AS `discount_text`,`p`.`limit_purchase_quantity` AS `limit_purchase_quantity`,`p`.`promo_remaining_text` AS `promo_remaining_text`,`p`.`promotion_text` AS `promotion_text`,`p`.`purchase_price_amount` AS `purchase_price_amount`,`p`.`purchase_price_unit` AS `purchase_price_unit`,`p`.`purchase_price_text` AS `purchase_price_text`,`p`.`month_sales_text` AS `month_sales_text`,`p`.`month_sales_qty` AS `month_sales_qty`,`p`.`want_to_buy_count` AS `want_to_buy_count`,`p`.`praise_rate_pct` AS `praise_rate_pct`,`p`.`like_count` AS `like_count`,`p`.`dislike_count` AS `dislike_count`,`p`.`praise_count` AS `praise_count`,`p`.`stock_text` AS `stock_text`,`p`.`stock_quantity` AS `stock_quantity`,`p`.`stock_unit` AS `stock_unit`,`p`.`sale_status` AS `sale_status`,`p`.`listing_status` AS `listing_status`,`p`.`is_standard` AS `is_standard`,`p`.`is_promo_item` AS `is_promo_item`,`p`.`is_recommended` AS `is_recommended`,`p`.`sellable_date_text` AS `sellable_date_text`,`p`.`gift_bag_text` AS `gift_bag_text`,`p`.`selling_points` AS `selling_points`,`p`.`picture_url` AS `picture_url`,`p`.`other_text` AS `other_text`,`p`.`evidence_uri` AS `evidence_uri`,`p`.`evidence_video_time` AS `evidence_video_time`,`p`.`created_at` AS `created_at`,row_number() OVER (PARTITION BY `p`.`channel_code`,`p`.`store_code`,`p`.`listing_key` ORDER BY `p`.`snapshot_hour` desc,`s`.`started_at` desc,`p`.`id` desc )  AS `rn`,max(`p`.`snapshot_hour`) OVER (PARTITION BY `p`.`channel_code`,`p`.`store_code` )  AS `store_latest_hour` from (`fact_store_product_snapshot` `p` join `store_snapshot` `s` on((`s`.`store_snapshot_id` = `p`.`store_snapshot_id`))) where (`s`.`status` in ('success','partial'))) `x` where ((`x`.`rn` = 1) and (`x`.`snapshot_hour` >= (`x`.`store_latest_hour` - interval 7 day)));
